code.source:
def repeat(times):
    def decorator(func):
        def wrapper(*args, **kwargs):
            for _ in range(times):
                func(*args, **kwargs)
        return wrapper
    return decorator

@repeat(3)
def hello(name):
    print("Hello", name)

hello("Asha")

import functools

def require(role):
    def decorator(func):
        @functools.wraps(func)
        def wrapper(user, *args, **kwargs):
            if user != role:
                return "denied"
            return func(user, *args, **kwargs)
        return wrapper
    return decorator

@require("admin")
def delete_all(user):
    return "deleted"

print(delete_all("admin"))
print(delete_all("guest"))
print(delete_all.__name__)

